/* The inner spacer — defines the inset geometry where the metal ring meets
   the interior (3 px for Button, 1-2 px for Circle) and carries the Circle dark
   hairline ('box-shadow: inset' rules below). Intentionally transparent so
   the wrapper's background propagates through to the punched shader centre,
   giving consumers a single surface tone to override. See "Single-surface
   background" in the file header for the rationale. */
.metal-fx-inner {
  position: absolute;
  inset: 3px;
  border-radius: inherit;
  z-index: 1;
  pointer-events: none;
}

.metal-fx-root[data-variant='button'][data-shape='pill'] .metal-fx-inner {
  border-radius: calc(var(--mfx-radius, 20px) - 3px);
}
.metal-fx-root[data-variant='button'][data-shape='circle'] .metal-fx-inner {
  border-radius: calc(var(--mfx-radius, 16px) - 3px);
}
.metal-fx-root[data-variant='circle'][data-shape='pill'] .metal-fx-inner {
  inset: 0;
  border-radius: var(--mfx-radius, 20px);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45);
}
.metal-fx-root[data-variant='circle'][data-shape='circle'] .metal-fx-inner {
  inset: 0;
  border-radius: var(--mfx-radius, 16px);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.45);
}
/* Circle-variant hairline alpha — light mode.
   Source-of-truth: index.html L2261-2267. The 0.45-alpha black inset that
   reads as a single-pixel frame against the dark interior is too heavy
   on a #ffffff inner: it ends up looking like a hard 2-px black ring
   against the iridescent shader. Suppressed entirely (alpha 0) — the
   shader's own iridescent rim already defines the silhouette in light
   mode, so an extra dark hairline only competes with it. The rule is
   kept (rather than deleted) as a tunable hook in case a future variant
   wants to re-introduce a soft edge. NOTE: we keep the dark-mode inset
   and border-radius values because — unlike index.html — our renderer
   does NOT overscan the canvas in light mode, so there is no 1-px gap
   between inner element and shader to compensate for. */
.metal-fx-root[data-theme='light'][data-variant='circle'][data-shape='pill'] .metal-fx-inner,
.metal-fx-root[data-theme='light'][data-variant='circle'][data-shape='circle'] .metal-fx-inner {
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0);
}

/* ─── Combined glow SVG (z=3) ──────────────────────────────────────────────
   Single SVG per instance that holds BOTH the wide-halo group
   (#mfx_haloTravel) and the catch-light group (#mfx_extraTravel), exactly
   mirroring canonical's _buildGlowSvgInner (index.html L8078). One
   mix-blend-mode: screen lifts the combined composite onto the shader
   ring; per-frame opacity attributes on each inner group still drive the
   independent fade-in / fade-out cycles for the halo and the catch-light.

   Why a single SVG: the circle variant anchors halo + catch-light at the same
   perimeter point, so they overlap in the bright zone. Two separately-
   screened SVGs would double-screen the overlap (A + B + C - AB - AC -
   BC + ABC instead of A + B + C - AB - AC once both groups composite
   in source-over inside one SVG and then screen against the host once).
   That overlap looked muted versus canonical specifically on the circle
   variant where both layers travel together.

   Source-of-truth opacity: #btnGlowSvg drops to 0.7 in dark and 0.2746 in
   light (index.html L632/L643). */
.metal-fx-glow-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  z-index: 3;
  pointer-events: none;
  opacity: 0.7;
}
.metal-fx-root[data-theme='light'] .metal-fx-glow-svg {
  /* Light-mode 1-px overscan mirrors .btn-glow-svg in metal.html so the
     halo stays glued to the visible silhouette (the shader ring there sits
     1 px outside the host's padding box). */
  inset: -1px;
  width: calc(100% + 2px);
  height: calc(100% + 2px);
  mix-blend-mode: multiply;
  /* Source-of-truth: html[data-theme="light"] #btnGlowSvg { opacity: 0.2746 }
     → −35 % from 0.4225 from the original 0.7 dark-mode opacity. */
  opacity: 0.2746;
  filter: saturate(5.355) brightness(0.78);
}
/* Circle light-mode small variants (e.g. 36×36 send button): the geometrically
   shrunk halo loses density when multiplied against #ffffff. Mirror the
   canonical override at index.html L2316 — bump saturation + drop brightness
   so the small glow holds together visually. */
.metal-fx-root[data-variant='circle'][data-shape='circle'][data-theme='light'] .metal-fx-glow-svg {
  filter: saturate(7.5) brightness(0.6);
}

/* The wrapped child — hoisted into z=5 so it sits above every overlay, with
   normalized chrome so consumer button styles don't fight the metal frame. */
.metal-fx-content {
  position: relative;
  z-index: 5;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  pointer-events: none;
}
.metal-fx-content > * {
  pointer-events: auto;
}
.metal-fx-root[data-normalize='true'] .metal-fx-content > * {
  background: transparent !important;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  /* Sizing: we deliberately DO NOT force \`width: 100%; height: 100%\` on the
     child here. That used to be the contract ("the wrapper is the visible
     button surface; the child stretches to fill it"), but it created a cyclic
     percentage dependency: the wrapper is \`inline-flex\` with no intrinsic
     size, .metal-fx-content is \`width/height: 100%\` of the wrapper, and the
     child was \`100%\` of .metal-fx-content. With nothing breaking the cycle,
     icon-only / class-sized children collapsed.

     The new contract: the child sizes itself (intrinsic content, CSS class,
     or inline style — all work), and the wrapper's \`inline-flex\` wraps it
     tightly. Consumers who want a metal frame BIGGER than the child (e.g.
     padding around an icon) size <MetalFx style={{ width, height }}> AND
     explicitly set width/height on the child to fill (or accept that the
     child renders at its intrinsic size, centered).

     Typography is intentionally NOT touched. We used to apply
     \`color: inherit; font: inherit;\` here to "match" the wrapper, but
     \`font: inherit\` is a shorthand that overrides font-family, font-size,
     font-weight, AND line-height on the child — which (a) shrank the
     button height (line-height changes propagate through the flex
     content box) and (b) scaled em-based icons / font-icons inside the
     child to whatever the wrapper inherited. The wrapper now stays out
     of the child's typography entirely; consumers who want typographic
     normalization can apply it themselves on the child element. */
}

[data-metal-fx-reflection] {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  overflow: hidden;
  z-index: 0;
  isolation: isolate;
}
.metal-fx-reflection-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: blur(4px) saturate(1.2) brightness(1.58);
}
.metal-fx-reflection-stroke-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: saturate(1.35) brightness(1.75);
}
/* Hosts that participate as reflection targets need positioning + isolation
   so the wrap composites only against the host (not the parent stack). The
   wrap injects these inline as well, but stating them here keeps reflections
   working on hosts that already have other inline styles applied. */
[data-metal-fx-reflect-host] {
  isolation: isolate;
}
`;

let injected = false;

export function ensureStylesInjected(): void {
  if (injected) return;
  if (typeof document === 'undefined') return;
  if (document.getElementById(STYLE_ID)) { injected = true; return; }
  const style = document.createElement('style');
  style.id = STYLE_ID;
  style.textContent = CSS;
  document.head.appendChild(style);
  injected = true;
}

import type { CSSProperties, ReactNode, HTMLAttributes, RefObject } from 'react';
import type { MaskFn } from './engine/renderer/core';

/**
 * Variant for the metal effect.
 * - 'button' (default): pill-shaped 134×40 baseline with shaderScale 1.6
 * - 'circle': compact 32×32 circle baseline with shaderScale 1.3
 *
 * In practice the wrapped child's measured dimensions drive the visible size —
 * the variant only controls the shader sampling scale and ring thickness.
 */
export type MetalFxVariant = 'button' | 'circle';

/**
 * Theme mode for the metal effect.
 *
 * - `auto` (default): follows the user's `prefers-color-scheme` and updates
 *   live when the OS / browser theme changes (also gracefully falls back to
 *   `dark` during SSR or when `matchMedia` is unavailable).
 * - `dark`: pin to the dark-mode tunings regardless of system preference.
 * - `light`: pin to the light-mode tunings regardless of system preference.
 *
 * Drive this from your app's theme state if you have a manual toggle that
 * doesn't follow the OS — otherwise `auto` is the right default.
 */
export type MetalFxTheme = 'dark' | 'light' | 'auto';

/**
 * Bundled preset names. Each preset ships both a dark and light mode block.
 */
export type MetalFxPreset = 'chromatic' | 'silver' | 'gold';

/**
 * A reflection target: either a bare ref, or a ref plus a per-target
 * `strength` multiplier (0..1+). Use the object form when a surface should
 * only catch a faint echo of the metal — a container the button sits inside,
 * for example — without turning down every other target.
 */
export type MetalFxReflectionTarget =
  | RefObject<HTMLElement | null>
  | { ref: RefObject<HTMLElement | null>; strength?: number };

/**
 * Props for the MetalFx React component.
 */
export interface MetalFxProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * The single host element to wrap with the metal effect. Must be a single
   * React node (button, anchor, div, ...). MetalFx measures this element each
   * frame via `ResizeObserver` and paints its canvas + glow on top.
   */
  children: ReactNode;

  /**
   * Variant — controls the shader sampling scale + ring width.
   * - `button` (default): pill-style ring at 1 px wide, scale 1.6
   * - `circle`: compact circle with a 2 px ring, scale 1.3
   */
  variant?: MetalFxVariant;

  /**
   * Color preset. All three presets ship both dark and light mode tunings —
   * `theme` picks the right side at runtime.
   * @default 'chromatic'
   */
  preset?: MetalFxPreset;

  /**
   * Theme mode. `'auto'` (default) resolves via
   * `matchMedia('(prefers-color-scheme: dark)')` and switches live when the
   * OS theme changes. Pass `'dark'` or `'light'` to pin a specific mode.
   * @default 'auto'
   */
  theme?: MetalFxTheme;

  /**
   * Effect strength (0..1). Multiplies the shader bitmap opacity and the glow
   * SVG alpha. The shader continues to animate at full intensity at any value;
   * only the rendered alpha onto the host is scaled. Lighter values let the
   * underlying child surface show through more strongly.
   * @default 1
   */
  strength?: number;

  /**
   * Multiplier on the glow only (halo + catch-light), on top of `strength`.
   * Use it when the shader runs at low `strength` but the glow should still
   * read — e.g. metal text. Clamped to 0..1 after multiplying.
   * @default 1
   */
  glowGain?: number;

  /**
   * Pause the shader animation. The visible canvas keeps the last painted
   * frame so the metal silhouette stays on screen.
   * @default false
   */
  paused?: boolean;

  /**
   * Optional explicit border radius (CSS px). When omitted, MetalFx reads the
   * computed border-radius of the wrapped child each resize.
   */
  borderRadius?: number;

  /**
   * When true, MetalFx normalizes the host element's outer chrome (border /
   * outline / box-shadow) so user-provided component styles don't clash with
   * the metal ring. Inner fills, typography, and content remain untouched.
   * @default true
   */
  normalizeHostStyles?: boolean;

  /**
   * Neighbour elements that should receive a soft proximity reflection of the
   * metal effect. Reflections only render when the resolved theme is `dark` —
   * pass-through in light mode (no DOM scan, no per-frame work).
   *
   * Pass refs to the sibling DOM elements you want to receive the reflection
   * (chips next to a send button, search field next to an Upgrade pill, ...).
   *
   * A target that *contains* the wrapped element (its parent card, say)
   * receives the reflection on both the nearest vertical and horizontal
   * inner edges. Pair with `{ ref, strength }` to keep that subtle.
   */
  reflectionTargets?: ReadonlyArray<MetalFxReflectionTarget>;

  /**
   * Disable the wandering halo overlay. The shader ring still renders.
   * @default false
   */
  disableGlow?: boolean;

  /**
   * Light rim along the top inside edge of the ring — an inner shadow from
   * above, like the one on metal text. `true` uses the design defaults
   * (white 90 %, offset 1 px, blur 0.5 px); pass an object to tune.
   * @default undefined (off)
   */
  innerShadow?: boolean | { offsetY?: number; blur?: number; alpha?: number; color?: string };

  /**
   * Override the shader sampling scale. Larger values zoom into the shared
   * shader (visibly bigger pattern features); smaller values zoom out.
   * Defaults to the variant's baseline (1.6 for `'button'`, 1.3 for
   * `'circle'`) multiplied by `scale`.
   */
  shaderScale?: number;

  /**
   * Override the ring thickness in CSS pixels. Defaults to the variant's
   * baseline (1 for `'button'`, 2 for `'circle'`) multiplied by `scale`.
   */
  ringCssPx?: number;

  /**
   * Master scale multiplier for every absolute-pixel constant the engine
   * uses internally. Set this when you render the wrapped element at a
   * non-1× size (e.g. inside a CSS `zoom: 2` container, or when you've
   * doubled all your Tailwind sizes by hand). It scales:
   *   - shader sampling (so pattern features grow proportionally)
   *   - ring thickness on the canvas
   *   - glow SVG stroke widths, blur radii, fade-circle radius, and the
   *     small inset/outward offsets that position the catch-light
   *   - reflection canvas stroke band, border-highlight thickness, and the
   *     reference draw width baseline
   * @default 1
   */
  scale?: number;

  /**
   * Custom alpha mask painter. When set, the shader is kept only where the
   * mask paints (device px, origin at the wrapper's top-left) and the ring
   * punch is skipped — for metal-filled text or glyphs. Pair with
   * `disableGlow`; the glow assumes a ring perimeter.
   */
  mask?: MaskFn;

  /**
   * How the glow is placed when `mask` is set. `'mask'` (default) samples
   * points inside the mask and clips the halo to it — right for metal text.
   * `'ring'` keeps the rounded-rect perimeter behaviour — a halo along the
   * element's edge — for a full-fill mask like a badge.
   */
  glowMode?: 'mask' | 'ring';

  /**
   * Forwarded class name for the wrapper element.
   */
  className?: string;

  /**
   * Forwarded inline styles for the wrapper element.
   */
  style?: CSSProperties;
}

/**
 * Bare metal-filled text — the Pro badge's glyph treatment without the pill.
 * Figma: Portfolio › 1471:40925 ("Plan Pro" card).
 *
 * MetalFx's `mask` paints the word with the same font and metrics as the
 * live span, so layout and hit-testing stay DOM. The metal is composited
 * over the live text, so `color` is the tone the shader blends onto — the
 * design's own colour, not white. The canvas is lifted above the content
 * layer and the glow (clipped to the glyphs) above that.
 */
import React, { useCallback, useEffect, useRef, type CSSProperties } from 'react';
import { MetalFx } from './MetalFx';
import type { MetalFxReflectionTarget, MetalFxTheme } from './types';
import type { MaskFn } from './engine/renderer/core';
import { gaussBlur } from './engine/glow/bake';
import { paintTextRun } from './engine/textMask';

/**
 * Figma inner shadow on the text (1471:40930): white 90 %, offset 0/1,
 * blur 0.5 — a hairline of light along the top inside edge of every glyph.
 * CSS has no inner shadow for text, so it's computed: glyph alpha minus the
 * same alpha shifted down by the offset leaves exactly that top rim, which is
 * then blurred and drawn white on an overlay above the metal.
 */
export interface TextInnerShadow { offsetY: number; blur: number; alpha: number }
const FIGMA_INNER_SHADOW: TextInnerShadow = { offsetY: 1, blur: 0.5, alpha: 0.9 };
/** Tuned on the demo's "Plan Pro" card. */
export const METAL_TEXT_DEFAULTS = Object.freeze({ metalOpacity: 0.62, shaderScale: 2.8, glowGain: 2.5, innerShadow: FIGMA_INNER_SHADOW });

function drawInnerShadow(cv: HTMLCanvasElement, root: HTMLElement, textEl: HTMLElement, sh: TextInnerShadow): void {
  const dpr = window.devicePixelRatio || 1;
  const rr = root.getBoundingClientRect();
  const w = Math.max(1, Math.round(rr.width * dpr)), h = Math.max(1, Math.round(rr.height * dpr));
  const off = document.createElement('canvas');
  off.width = w; off.height = h;
  const og = off.getContext('2d', { willReadFrequently: true });
  const g = cv.getContext('2d');
  if (!og || !g) return;
  og.fillStyle = '#fff';
  paintTextRun(og, root, textEl, dpr);
  const d = og.getImageData(0, 0, w, h).data;
  const n = w * h;
  const a = new Float32Array(n);
  for (let i = 0, j = 3; i < n; i++, j += 4) a[i] = d[j] / 255;
  const shift = Math.max(1, Math.round(sh.offsetY * dpr)) * w;
  const rim = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const above = i >= shift ? a[i - shift] : 0;
    // Coverage the shifted glyph doesn't cover — the strip along the top
    // edge. A difference, not a product: on anti-aliased side edges both
    // values are partial and a product lit every edge of every glyph.
    rim[i] = Math.max(0, a[i] - above);
  }
  const blurred = gaussBlur(rim, w, h, sh.blur * dpr);
  cv.width = w; cv.height = h;
  cv.style.width = `${rr.width}px`; cv.style.height = `${rr.height}px`;
  const img = g.createImageData(w, h);
  const o = img.data;
  for (let i = 0, j = 0; i < n; i++, j += 4) {
    o[j] = 255; o[j + 1] = 255; o[j + 2] = 255;
    // Inner shadow: clipped to the glyph, so the blur never leaks outside
    // the letterform (it read as a halo, worst when zoomed in).
    o[j + 3] = Math.round(Math.min(1, blurred[i] * a[i] * sh.alpha) * 255);
  }
  g.putImageData(img, 0, 0);
}

// MetalFx dresses its root as a button: fill, inset rims (::before/::after)
// and the inner hairline. Bare text wants none of that — only the glyphs.
const BARE_STYLE_ID = 'mfx-bare-style';
const BARE_CSS =
  '.metal-fx-root[data-mfx-bare]{background:transparent!important}' +
  '.metal-fx-root[data-mfx-bare]::before,.metal-fx-root[data-mfx-bare]::after{box-shadow:none!important}' +
  '.metal-fx-root[data-mfx-bare] .metal-fx-inner{display:none!important}';

export function MetalText({
  children,
  font,
  color,
  strength = 1,
  theme,
  reflectionTargets,
  className,
  innerShadow = FIGMA_INNER_SHADOW,
  glow = false,
  glowGain = METAL_TEXT_DEFAULTS.glowGain,
  metalOpacity = METAL_TEXT_DEFAULTS.metalOpacity,
  shaderScale = METAL_TEXT_DEFAULTS.shaderScale,
}: {
  children: string;
  /** CSS `font` shorthand for the live span, e.g. `500 24px/1 Inter, sans-serif`. */
  font: string;
  /** Base text colour from the design; the metal composites over it. */
  color: string;
  strength?: number;
  theme?: MetalFxTheme;
  reflectionTargets?: ReadonlyArray<MetalFxReflectionTarget>;
  className?: string;
  /** Top-edge light rim inside the glyphs. Pass null to disable. */
  innerShadow?: TextInnerShadow | null;
  /** Halo on the glyphs. Off by default — the design has none. */
  glow?: boolean;
  /** Glow multiplier when `glow` is on. */
  glowGain?: number;
  /** How much metal shows over the base colour (0..1), multiplied with `strength`. */
  metalOpacity?: number;
  /** Zoom of the metal inside the glyphs. */
  shaderScale?: number;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!document.getElementById(BARE_STYLE_ID)) {
      const st = document.createElement('style');
      st.id = BARE_STYLE_ID;
      st.textContent = BARE_CSS;
      document.head.appendChild(st);
    }
    rootRef.current?.setAttribute('data-mfx-bare', '');
    const cv = rootRef.current?.querySelector<HTMLCanvasElement>('canvas.metal-fx-canvas');
    if (cv) cv.style.zIndex = '6';
    const host = rootRef.current?.querySelector<HTMLElement>('.metal-fx-glow-svg')?.parentElement;
    if (host) host.style.zIndex = '7';
  }, []);

  // Inner-shadow overlay: above the metal (6) and the glow (7), redrawn when
  // fonts land or the box changes. Static otherwise.
  useEffect(() => {
    const root = rootRef.current, t = textRef.current;
    if (!root || !t || !innerShadow) return;
    const cv = document.createElement('canvas');
    cv.className = 'metal-fx-text-rim';
    cv.setAttribute('aria-hidden', 'true');
    cv.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;z-index:8';
    root.appendChild(cv);
    const draw = () => drawInnerShadow(cv, root, t, innerShadow);
    draw();
    let alive = true;
    document.fonts?.ready.then(() => { if (alive) draw(); });
    const ro = new ResizeObserver(draw);
    ro.observe(root);
    // Browser zoom changes the DPR without changing the CSS box, so the
    // ResizeObserver stays quiet; re-rasterise from a resolution query.
    let mql: MediaQueryList | null = null;
    const watchDpr = () => {
      mql?.removeEventListener('change', onDpr);
      mql = typeof window.matchMedia === 'function' ? window.matchMedia(`(resolution: ${window.devicePixelRatio || 1}dppx)`) : null;
      mql?.addEventListener('change', onDpr);
    };
    const onDpr = () => { if (!alive) return; draw(); watchDpr(); };
    watchDpr();
    return () => { alive = false; ro.disconnect(); mql?.removeEventListener('change', onDpr); cv.remove(); };
  }, [innerShadow]);

  const mask = useCallback<MaskFn>((ctx, _w, _h, dpr) => {
    const root = rootRef.current, t = textRef.current;
    if (root && t) paintTextRun(ctx, root, t, dpr);
  }, []);

  const style: CSSProperties = { font, color, letterSpacing: 0, whiteSpace: 'nowrap' };

  return (
    <MetalFx
      ref={rootRef}
      preset="chromatic"
      theme={theme}
      strength={strength * metalOpacity}
      glowGain={glowGain}
      disableGlow={!glow}
      mask={mask}
      reflectionTargets={reflectionTargets}
      shaderScale={shaderScale}
      borderRadius={4}
      style={{ background: 'transparent', borderRadius: 4 }}
    >
      <span ref={textRef} className={className} style={style} aria-label={children}>
        {children}
      </span>
    </MetalFx>
  );
}

/**
 * Paint an element's text run onto a canvas with the DOM's own font and
 * metrics, so canvas glyphs land on the DOM glyphs to within a device px.
 * Shared by the Pro badge's metal fill and the text reflection mask.
 *
 * `ctx` is expected in device px with origin at `root`'s top-left; the
 * function scales by `dpr` internally.
 */
export function paintTextRun(
  ctx: CanvasRenderingContext2D,
  root: HTMLElement,
  textEl: HTMLElement,
  dpr: number
): void {
  const cs = getComputedStyle(textEl);
  const rr = root.getBoundingClientRect();
  const range = document.createRange();
  range.selectNodeContents(textEl);
  const tr = range.getBoundingClientRect();
  range.detach();
  ctx.save();
  ctx.scale(dpr, dpr);
  ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  const text = textEl.textContent ?? '';
  const m = ctx.measureText(text);
  const asc = m.fontBoundingBoxAscent ?? parseFloat(cs.fontSize) * 0.9;
  const desc = m.fontBoundingBoxDescent ?? parseFloat(cs.fontSize) * 0.2;
  const x = tr.left - rr.left;
  const baseline = tr.top - rr.top + (tr.height - (asc + desc)) / 2 + asc;
  ctx.fillText(text, x, baseline);
  ctx.restore();
}

/** Render `textEl`'s glyphs white-on-transparent over `root`'s box → data URL. */
export function textMaskDataUrl(root: HTMLElement, textEl: HTMLElement): string | null {
  const dpr = window.devicePixelRatio || 1;
  const rr = root.getBoundingClientRect();
  const c = document.createElement('canvas');
  c.width = Math.max(1, Math.round(rr.width * dpr));
  c.height = Math.max(1, Math.round(rr.height * dpr));
  const g = c.getContext('2d');
  if (!g) return null;
  g.fillStyle = '#fff';
  paintTextRun(g, root, textEl, dpr);
  return c.toDataURL('image/png');
}

/**
 * "New" badge — Figma: Portfolio › tab 3 (1458:40880), applied verbatim.
 *
 *   45×25, pill r 55.556. Layers bottom→top:
 *     1. white fill
 *     2. metal texture (a static PNG in Figma — here the live shader, via a
 *        full-pill mask so it covers the fill)
 *     3. gradient rgba(255,255,255,.6) → 0, top→bottom
 *     3b. clean white core under the label — transitions.dev get-pro-button
 *         mechanism inverted: radial ellipse 46%, solid to `core`, ramp over
 *         `coreBlur`, so the text sits on white and metal creeps in at the rim
 *     4. text: Inter Semi Bold 12.222/1.4 #323232, box 26.667×13.333
 *     5. inset shadows: 0 0 8.333 #fff ×2, 0 0 0 0.833 rgba(255,255,255,.5),
 *        0 0.833 0 rgba(255,255,255,.78)
 *
 * The gradient AND the inset shadows have to sit above the metal canvas
 * (z 0) and below the text (content z 5) — on the root they'd be painted
 * under the opaque metal and vanish. Both live on one overlay inside the
 * content layer, one level down: MetalFx normalises the *direct* child's
 * background/box-shadow to transparent/none, so the overlay is nested under
 * a plain wrapper to keep them.
 */
import React, { useCallback, useRef } from 'react';
import { MetalFx } from './MetalFx';
import type { MetalFxReflectionTarget, MetalFxTheme } from './types';
import type { MaskFn } from './engine/renderer/core';

const RADIUS = 55.556;
const W = 45, H = 25;
const TEXT_W = 26.667;
const PAD_X = (W - TEXT_W) / 2;

const LAYER: React.CSSProperties = { position: 'absolute', inset: 0, pointerEvents: 'none' };

/** `glow` scales the two soft inner glows; the hairline rims stay as designed. */
const shadowFor = (k: number, glow: number) =>
  `inset 0px 0px ${8.333 * k}px 0px rgba(255,255,255,${glow}), ` +
  `inset 0px 0px ${8.333 * k}px 0px rgba(255,255,255,${glow}), ` +
  `inset 0px 0px 0px ${0.833 * k}px rgba(255,255,255,0.5), ` +
  `inset 0px ${0.833 * k}px 0px 0px rgba(255,255,255,0.78)`;

/** Tuned on the demo's "Live mode · New" card. */
export const METAL_BADGE_DEFAULTS = Object.freeze({
  metalOpacity: 0.8,
  shaderScale: 1.6,
  /** White core under the label: solid radius (% of ellipse), ramp width, opacity, ellipse size (% of box). */
  core: Object.freeze({ r: 46, blur: 100, a: 0.94, size: 49 }),
  gradient: 0,
  glow: 0.41,
});

export interface MetalBadgeCore { r: number; blur: number; a: number; size: number }

export function MetalBadge({
  children = 'New',
  strength = 1,
  theme,
  scale = 1,
  reflectionTargets,
  metalOpacity = METAL_BADGE_DEFAULTS.metalOpacity,
  shaderScale = METAL_BADGE_DEFAULTS.shaderScale,
  core = METAL_BADGE_DEFAULTS.core,
  gradient = METAL_BADGE_DEFAULTS.gradient,
  glow = METAL_BADGE_DEFAULTS.glow,
  textColor = '#323232',
}: {
  children?: string;
  strength?: number;
  theme?: MetalFxTheme;
  /** Size multiplier on the Figma metrics (45×25, 12.222px). */
  scale?: number;
  reflectionTargets?: ReadonlyArray<MetalFxReflectionTarget>;
  /** How much metal shows over the white fill (0..1), multiplied with `strength`. */
  metalOpacity?: number;
  shaderScale?: number;
  core?: MetalBadgeCore;
  /** Top→bottom white wash strength (0..1). */
  gradient?: number;
  /** Inner white glow strength (0..1). */
  glow?: number;
  textColor?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const opacity = metalOpacity;

  // Full-fill mask: the pill itself.
  const mask = useCallback<MaskFn>((ctx, w, h, dpr) => {
    ctx.beginPath();
    ctx.roundRect(0, 0, w, h, RADIUS * dpr);
    ctx.fill();
  }, []);

  return (
    <MetalFx
      ref={rootRef}
      preset="chromatic"
      theme={theme}
      strength={strength * opacity}
      shaderScale={shaderScale}
      mask={mask}
      glowMode="ring"
      reflectionTargets={reflectionTargets}
      borderRadius={RADIUS * scale}
      style={{ background: '#ffffff', borderRadius: RADIUS * scale }}
    >
      {/* Inline layout only — no utility classes, so the badge renders the
          same with or without a CSS framework on the host page. */}
      <div style={{ position: 'relative', width: W * scale, height: H * scale, borderRadius: RADIUS * scale }}>
        {/* layer 3b — clean white core under the label (rim-only metal) */}
        <div
          aria-hidden="true"
          style={{
            ...LAYER,
            borderRadius: RADIUS * scale,
            // Stops are relative to the ellipse radius, so 100% = its edge.
            background: `radial-gradient(ellipse ${core.size}% ${core.size}% at 50% 50%, rgba(255,255,255,1) ${core.r}%, rgba(255,255,255,0) ${Math.min(100, core.r + core.blur)}%)`,
            opacity: core.a,
          }}
        />
        {/* layers 3 + 5 — white gradient and inset rims, over the metal */}
        <div
          aria-hidden="true"
          style={{
            ...LAYER,
            borderRadius: RADIUS * scale,
            background: `linear-gradient(to bottom, rgba(255,255,255,${gradient}), rgba(255,255,255,0))`,
            boxShadow: shadowFor(scale, glow),
          }}
        />
        <span
          style={{
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxSizing: 'border-box',
            width: W * scale,
            height: H * scale,
            paddingLeft: PAD_X * scale,
            paddingRight: PAD_X * scale,
            font: `600 ${12.222 * scale}px/1.4 Inter, sans-serif`,
            color: textColor,
            letterSpacing: 0,
            whiteSpace: 'nowrap',
          }}
          aria-label={children}
        >
          {children}
        </span>
      </div>
    </MetalFx>
  );
}

import { useEffect, type RefObject } from 'react';
import { redrawInstance, setInstanceDeform } from './engine/renderer/loop';
import type { DeformLayers } from './engine/renderer/core';
import { BEND, type BendConfig } from './engine/bend/config';

/**
 * Cursor-driven local deformation ("liquid dent") for a MetalFx root.
 *
 * Field
 * ─────
 * Two gaussian blobs centred at `c` (which lags the cursor by `follow`):
 *   • directional: `amp · g_bend(r)` — a 2-D spring chasing the cursor's
 *     smoothed velocity × gain, so motion toward the centre pushes the ring
 *     in and motion away drags it out; recoils on release.
 *   • liquid: `(p − c)/σ · g_liq(r) · la` — the gradient of a bump, i.e. a
 *     divergent push away from the contact point. This term *stretches*
 *     material rather than sliding it, so the stroke thins under the cursor
 *     and thickens either side. `la` is its own slower spring; pressure is 1
 *     with the cursor on the ring, fading over `liquidReach`.
 *
 * Two render paths, chosen by `applyTo`:
 *
 * `ring` — vector. The engine masks the ring with a rounded-rect outline it
 * traces every frame; we hand it a `DeformFn` that displaces those outline
 * points, plus the fill / rim / hairline that normally live on CSS boxes so
 * they bend along. Edges stay anti-aliased at any stretch. The instance is
 * redrawn from here at the pointer's frame rate, since the shared loop only
 * composites at 15 fps.
 *
 * `all` — SVG `feDisplacementMap` on the whole root. Bends the content too,
 * but the sampler duplicates source pixels where material is stretched, so
 * quality degrades with amplitude. Kept for comparison.
 */
export function useMetalBend(ref: RefObject<HTMLElement | null>, getCfg: () => BendConfig = () => BEND): void {
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof document === 'undefined') return;

    const ring = el.querySelector<HTMLCanvasElement>('canvas.metal-fx-canvas');
    const inner = el.querySelector<HTMLElement>('.metal-fx-inner');

    // ── shared field state ──────────────────────────────────────────
    let pointer: { x: number; y: number } | null = null;
    let lastPointer: { x: number; y: number; t: number } | null = null;
    let pressed = false;
    let active = false;
    let cx = 0, cy = 0;          // blob centre, element-local px
    let ax = 0, ay = 0;          // directional displacement (px)
    let vax = 0, vay = 0;
    let la = 0, vla = 0;         // liquid amplitude
    let stx = 0, sty = 0, stl = 0; // low-passed targets (see smoothMs)
    let pressure = 0;
    let env = 0;                 // hover envelope 0..1 — no pops on enter/leave
    let svx = 0, svy = 0;        // smoothed cursor velocity, px/s
    let raf = 0, last = 0;
    // Redraw gate: physics integrates at display rate, but the canvas +
    // glow-mask rebuild is capped at 60 fps and skipped when nothing moved
    // more than 0.05 px — on a 120 Hz display that halves the bend's cost.
    let drawT = 0, dAx = NaN, dAy = NaN, dLa = NaN, dCx = NaN, dCy = NaN;

    // Per-frame constants for the field evaluators.
    let fDirX = 0, fDirY = 0, fRadK = 0, fS2b = 1, fS2l = 1;
    const evalField = (x: number, y: number, out: { x: number; y: number }) => {
      const dx = x - cx, dy = y - cy;
      const q = dx * dx + dy * dy;
      const gb = Math.exp(-q / fS2b);
      const gl = Math.exp(-q / fS2l);
      out.x = fDirX * gb + dx * fRadK * gl;
      out.y = fDirY * gb + dy * fRadK * gl;
    };
    const _f = { x: 0, y: 0 };
    const deform = (x: number, y: number, out: { x: number; y: number }) => {
      evalField(x, y, _f);
      out.x = x + _f.x;
      out.y = y + _f.y;
    };

    // ── vector path (ring mode) ─────────────────────────────────────
    const STYLE_ID = 'mfx-bend-style';
    if (!document.getElementById(STYLE_ID)) {
      const st = document.createElement('style');
      st.id = STYLE_ID;
      st.textContent = '.metal-fx-root[data-mfx-bend]::before,.metal-fx-root[data-mfx-bend]::after{box-shadow:none!important}';
      document.head.appendChild(st);
    }
    let vectorOn = false;
    let layers: DeformLayers | null = null;
    const prevRootBg = el.style.background;
    const prevInnerVis = inner?.style.visibility ?? '';

    /** "rgba(…) 0px 0px 0px 2px inset" → { color, spread } for the first shadow. */
    const parseShadow = (v: string): { color: string; spread: number } | null => {
      if (!v || v === 'none') return null;
      const m = v.match(/^(rgba?\([^)]*\)|#[0-9a-fA-F]+|[a-z]+)\s+(-?[\d.]+)px\s+(-?[\d.]+)px\s+(-?[\d.]+)px\s+(-?[\d.]+)px/);
      if (!m) return null;
      return { color: m[1], spread: Math.abs(parseFloat(m[5])) };
    };
    const vectorStart = (overscan: number) => {
      if (vectorOn || !ring) return;
      const rim = parseShadow(getComputedStyle(el, '::after').boxShadow);
      const hair = inner ? parseShadow(getComputedStyle(inner).boxShadow) : null;
      const innerInset = inner ? parseFloat(getComputedStyle(inner).inset) || 0 : 0;
      layers = {
        fill: getComputedStyle(el).backgroundColor,
        rim: rim && rim.spread > 0 ? { inset: 0, width: rim.spread, color: rim.color } : null,
        hairline: hair && hair.spread > 0 ? { inset: innerInset, width: hair.spread, color: hair.color } : null,
      };
      el.style.background = 'transparent';
      el.setAttribute('data-mfx-bend', '');
      if (inner) inner.style.visibility = 'hidden';
      setInstanceDeform(ring, deform, layers, overscan);
      vectorOn = true;
    };
    const vectorStop = () => {
      if (!vectorOn || !ring) return;
      setInstanceDeform(ring, null, null, 0);
      el.style.background = prevRootBg;
      el.removeAttribute('data-mfx-bend');
      if (inner) inner.style.visibility = prevInnerVis;
      vectorOn = false;
    };

    // ── filter path (all mode) ──────────────────────────────────────
    const id = `mfx-bend-${Math.random().toString(36).slice(2, 8)}`;
    const NS = 'http://www.w3.org/2000/svg';
    const REGION = 0.75;
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('aria-hidden', 'true');
    svg.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden;pointer-events:none';
    const filter = document.createElementNS(NS, 'filter');
    filter.setAttribute('id', id);
    filter.setAttribute('x', `-${REGION * 100}%`); filter.setAttribute('y', `-${REGION * 100}%`);
    filter.setAttribute('width', `${(1 + 2 * REGION) * 100}%`); filter.setAttribute('height', `${(1 + 2 * REGION) * 100}%`);
    filter.setAttribute('color-interpolation-filters', 'sRGB');
    const feFlood = document.createElementNS(NS, 'feFlood');
    feFlood.setAttribute('flood-color', 'rgb(128,128,0)');
    feFlood.setAttribute('flood-opacity', '1');
    feFlood.setAttribute('result', 'neutral');
    const feImage = document.createElementNS(NS, 'feImage');
    feImage.setAttribute('result', 'img');
    feImage.setAttribute('preserveAspectRatio', 'none');
    const feComp = document.createElementNS(NS, 'feComposite');
    feComp.setAttribute('in', 'img'); feComp.setAttribute('in2', 'neutral');
    feComp.setAttribute('operator', 'over'); feComp.setAttribute('result', 'map');
    const feDisp = document.createElementNS(NS, 'feDisplacementMap');
    feDisp.setAttribute('in', 'SourceGraphic'); feDisp.setAttribute('in2', 'map');
    feDisp.setAttribute('xChannelSelector', 'R'); feDisp.setAttribute('yChannelSelector', 'G');
    feDisp.setAttribute('result', 'bent');
    const feSmooth = document.createElementNS(NS, 'feGaussianBlur');
    feSmooth.setAttribute('in', 'bent'); feSmooth.setAttribute('stdDeviation', '0');
    for (const n of [feFlood, feImage, feComp, feDisp, feSmooth]) filter.appendChild(n);
    svg.appendChild(filter);
    document.body.appendChild(svg);

    const map = document.createElement('canvas');
    const mctx = map.getContext('2d', { alpha: false, willReadFrequently: true });
    let img: ImageData | null = null;
    let img32: Uint32Array | null = null;
    const NEUTRAL = 0xff008080;
    let filterOn = false;
    const prevFilter = el.style.filter;
    const filterStop = () => {
      if (!filterOn) return;
      el.style.filter = prevFilter;
      filterOn = false;
    };
    const filterFrame = (cfg: BendConfig, W: number, H: number, scale: number) => {
      if (!mctx) return;
      const res = Math.max(0.25, cfg.mapRes);
      const mx = -W * REGION, my = -H * REGION, mw = W * (1 + 2 * REGION), mh = H * (1 + 2 * REGION);
      const pw = Math.max(2, Math.round(mw * res)), ph = Math.max(2, Math.round(mh * res));
      if (map.width !== pw || map.height !== ph || !img || !img32) {
        map.width = pw; map.height = ph;
        img = mctx.createImageData(pw, ph);
        img32 = new Uint32Array(img.data.buffer);
      }
      img32.fill(NEUTRAL);
      const data = img.data;
      const ext = 3 * Math.max(cfg.blob, cfg.liquidBlob);
      const px0 = Math.max(0, Math.floor((cx - ext - mx) * res));
      const px1 = Math.min(pw - 1, Math.ceil((cx + ext - mx) * res));
      const py0 = Math.max(0, Math.floor((cy - ext - my) * res));
      const py1 = Math.min(ph - 1, Math.ceil((cy + ext - my) * res));
      const inv = 255 / scale;
      for (let py = py0; py <= py1; py++) {
        const y = my + (py + 0.5) / res;
        let i = (py * pw + px0) * 4;
        for (let px = px0; px <= px1; px++, i += 4) {
          const x = mx + (px + 0.5) / res;
          evalField(x, y, _f);
          let r = 127.5 - _f.x * inv; r = r < 0 ? 0 : r > 255 ? 255 : r;
          let g = 127.5 - _f.y * inv; g = g < 0 ? 0 : g > 255 ? 255 : g;
          data[i] = r; data[i + 1] = g;
        }
      }
      mctx.putImageData(img, 0, 0);
      feImage.setAttribute('x', mx.toFixed(2)); feImage.setAttribute('y', my.toFixed(2));
      feImage.setAttribute('width', mw.toFixed(2)); feImage.setAttribute('height', mh.toFixed(2));
      feImage.setAttribute('href', map.toDataURL('image/png'));
      feDisp.setAttribute('scale', scale.toFixed(2));
      feSmooth.setAttribute('stdDeviation', Math.max(0, cfg.smooth).toFixed(3));
      if (!filterOn) { el.style.filter = `url(#${id})`; filterOn = true; }
    };

    // ── simulation ──────────────────────────────────────────────────
    const kick = () => {
      if (raf !== 0) return;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };

    const step = (now: number) => {
      raf = 0;
      const cfg = getCfg();
      const dt = Math.min(0.032, Math.max(0.001, (now - last) / 1000));
      last = now;

      const r = el.getBoundingClientRect();
      const W = r.width, H = r.height;
      const ecx = W / 2, ecy = H / 2;

      let tx = 0, ty = 0;
      pressure = 0;
      if (cfg.enabled && pointer) {
        const lx = pointer.x - r.left, ly = pointer.y - r.top;
        const ddx = lx - ecx, ddy = ly - ecy;
        const d = Math.hypot(ddx, ddy);
        const R = Math.min(W, H) / 2;
        const reach = Math.max(W, H) / 2 + cfg.reach;
        const wasActive = active;
        active = d < reach;
        const u = Math.max(0, 1 - Math.abs(d - R) / Math.max(1, cfg.liquidReach));
        pressure = u * u * (3 - 2 * u);
        if (active) {
          if (!wasActive) { cx = lx; cy = ly; }
          // `follow` is defined per 60 Hz frame; convert to this frame's dt.
          const fa = 1 - Math.pow(1 - Math.min(0.999, cfg.follow), dt * 60);
          cx += (lx - cx) * fa;
          cy += (ly - cy) * fa;
          const edgeFade = 1 - Math.max(0, (d - (reach - cfg.reach)) / cfg.reach);
          // Transient kick from cursor speed.
          tx = svx * (cfg.gain / 100) * edgeFade;
          ty = svy * (cfg.gain / 100) * edgeFade;
          // Position-based, so the dent holds while the cursor sits there.
          // Inside the edge: press toward the centre by penetration.
          // Outside: pull toward the cursor, fading to zero at reach.
          const ux = d > 0.001 ? ddx / d : 0, uy = d > 0.001 ? ddy / d : 0;
          const pen = R - d;
          if (pen > 0) {
            const m = pen * cfg.pressGain;
            tx -= ux * m; ty -= uy * m;
          } else {
            const out = -pen;
            const f = Math.max(0, 1 - out / Math.max(1, cfg.reach));
            const m = out * cfg.pullGain * (f * f * (3 - 2 * f));
            tx += ux * m; ty += uy * m;
          }
          const tm = Math.hypot(tx, ty);
          if (tm > cfg.maxDisp) { tx *= cfg.maxDisp / tm; ty *= cfg.maxDisp / tm; }
        }
      } else {
        active = false;
      }
      svx *= Math.exp(-dt * 12); svy *= Math.exp(-dt * 12);

      // Low-pass the targets. Springs then chase a smooth signal instead of a
      // stepping one — the stepping is what read as "unnatural" on fast sweeps.
      const sa = 1 - Math.exp(-(dt * 1000) / Math.max(1, cfg.smoothMs));
      stx += (tx - stx) * sa;
      sty += (ty - sty) * sa;

      const m = Math.max(0.05, cfg.mass);
      vax += ((-cfg.stiffness * (ax - stx) - cfg.damping * vax) / m) * dt;
      vay += ((-cfg.stiffness * (ay - sty) - cfg.damping * vay) / m) * dt;
      ax += vax * dt; ay += vay * dt;

      const pressAmt = pressed && active && cfg.enabled ? cfg.press : 0;
      const tl = active && cfg.enabled ? cfg.liquid * (pressure + (pressed ? 0.5 : 0)) : 0;
      stl += (tl - stl) * sa;
      vla += ((-cfg.liquidStiffness * (la - stl) - cfg.liquidDamping * vla) / m) * dt;
      la += vla * dt;

      // Envelope: exponential approach, ~95% of the way by fadeIn/OutMs.
      const envTarget = active && cfg.enabled ? 1 : 0;
      const tauMs = Math.max(1, envTarget ? cfg.fadeInMs : cfg.fadeOutMs) / 3;
      env += (envTarget - env) * (1 - Math.exp(-(dt * 1000) / tauMs));
      if (env < 0.002 && envTarget === 0) env = 0;

      const amp = Math.hypot(ax, ay);
      const idle = !active && env === 0 && amp < 0.05 && Math.hypot(vax, vay) < 1 && Math.abs(la) < 0.05 && pressAmt === 0;

      // Mode switch releases whichever path was active.
      if (cfg.applyTo === 'ring') filterStop(); else vectorStop();

      if (idle) {
        ax = ay = vax = vay = la = vla = 0;
        stx = sty = stl = 0;
        dAx = dAy = dLa = dCx = dCy = NaN;
        vectorStop();
        filterStop();
        return;
      }

      // Field constants for this frame. The envelope scales the whole field.
      const k = Math.max(0, cfg.strength) * env;
      let pdx = ecx - cx, pdy = ecy - cy;
      const pl = Math.hypot(pdx, pdy) || 1; pdx /= pl; pdy /= pl;
      const sb = Math.max(0.5, cfg.blob), sl = Math.max(0.5, cfg.liquidBlob);
      fS2b = 2 * sb * sb; fS2l = 2 * sl * sl;
      fDirX = (ax + pdx * pressAmt) * k;
      fDirY = (ay + pdy * pressAmt) * k;
      fRadK = (la / sl) * k;

      const moved = !(Math.abs(ax - dAx) < 0.05 && Math.abs(ay - dAy) < 0.05 && Math.abs(la - dLa) < 0.05 &&
                      Math.abs(cx - dCx) < 0.05 && Math.abs(cy - dCy) < 0.05);
      const due = now - drawT >= 1000 / 60 - 0.5;
      if (moved && due) {
        drawT = now; dAx = ax; dAy = ay; dLa = la; dCx = cx; dCy = cy;
        if (cfg.applyTo === 'ring' && ring) {
          // Overscan budget: the furthest any point can travel.
          const reachPx = Math.ceil((cfg.maxDisp + cfg.liquid * 1.5) * Math.max(1, cfg.strength)) + 4;
          vectorStart(reachPx);
          redrawInstance(ring);
        } else {
          const scale = Math.max(1, (cfg.maxDisp + cfg.liquid * 1.5) * 2 * Math.max(1, cfg.strength));
          filterFrame(cfg, W, H, scale);
        }
      } else if (cfg.applyTo === 'ring' && ring && !vectorOn) {
        vectorStart(Math.ceil((cfg.maxDisp + cfg.liquid * 1.5) * Math.max(1, cfg.strength)) + 4);
      }

      raf = requestAnimationFrame(step);
    };

    const onMove = (e: PointerEvent) => {
      const now = performance.now();
      if (lastPointer) {
        const dt = Math.max(0.004, (now - lastPointer.t) / 1000);
        // ~40 ms time constant regardless of event rate.
        const a = 1 - Math.exp(-dt / 0.04);
        svx += ((e.clientX - lastPointer.x) / dt - svx) * a;
        svy += ((e.clientY - lastPointer.y) / dt - svy) * a;
      }
      lastPointer = { x: e.clientX, y: e.clientY, t: now };
      pointer = { x: e.clientX, y: e.clientY };
      kick();
    };
    const onLeave = () => { pointer = null; lastPointer = null; kick(); };
    const onDown = () => { pressed = true; kick(); };
    const onUp = () => { pressed = false; kick(); };

    document.addEventListener('pointermove', onMove, { passive: true });
    document.addEventListener('pointerleave', onLeave);
    window.addEventListener('blur', onLeave);
    el.addEventListener('pointerdown', onDown);
    document.addEventListener('pointerup', onUp);
    document.addEventListener('pointercancel', onUp);

    return () => {
      if (raf !== 0) cancelAnimationFrame(raf);
      document.removeEventListener('pointermove', onMove);
      document.removeEventListener('pointerleave', onLeave);
      window.removeEventListener('blur', onLeave);
      el.removeEventListener('pointerdown', onDown);
      document.removeEventListener('pointerup', onUp);
      document.removeEventListener('pointercancel', onUp);
      vectorStop();
      filterStop();
      if (svg.parentNode) svg.parentNode.removeChild(svg);
    };
  }, [ref, getCfg]);
}

/**
 * Live config for the cursor "bend" effect — a local liquid dent.
 *
 * The cursor carries a blob of displacement that rides the ring: moving
 * toward the button's centre dents the edge inward, moving away drags it
 * outward, and on release the bulge springs back. Implemented as an SVG
 * `feDisplacementMap` over the whole MetalFx root (button, ring, glow), with
 * the vector field regenerated each frame into a small canvas.
 *
 * Mutable singleton, read every frame by `useBend`.
 */
export interface BendConfig {
  enabled: boolean;
  /** What deforms. `ring` = the metal canvas only; button content and glow
   *  stay rigid. `all` = the whole MetalFx root. */
  applyTo: 'ring' | 'all';
  /** Global amplitude multiplier on the whole displacement field. */
  strength: number;
  /** Time for the effect to ease in after the cursor arrives, ms. Without
   *  this the directional spring lands the dent in 2–3 frames — a pop. */
  fadeInMs: number;
  /** Time for the effect to ease out after the cursor leaves, ms. */
  fadeOutMs: number;
  /** Low-pass on the field's *target* before the spring sees it, ms. A fast
   *  sweep across the ring flips press→pull and swings the direction vector
   *  within a frame; this keeps the dent from snapping to each new target. */
  smoothMs: number;
  /** How far beyond the element's edge the cursor is still felt, CSS px. */
  reach: number;
  /** Area of the directional bend (gaussian σ), CSS px. */
  blob: number;
  /** Area of the liquid push (gaussian σ), CSS px. Independent of `blob`. */
  liquidBlob: number;
  /** Displacement cap, CSS px. Also sets the filter's `scale`. */
  maxDisp: number;
  /** Displacement px produced per 100 px/s of cursor speed — a transient
   *  kick on fast moves. 0 disables. */
  gain: number;
  /** Position-based press: dent px per px the cursor sits inside the ring's
   *  edge, pushing toward the centre. Holds while the cursor stays. */
  pressGain: number;
  /** Position-based pull: bulge px per px the cursor sits outside the edge
   *  (within `reach`), dragging the ring toward the cursor — the sticky part. */
  pullGain: number;
  /** Extra inward dent (toward element centre) while pressed, px. */
  press: number;
  /** Radial push away from the contact point, px at full pressure. This is
   *  the divergent part of the field — it *stretches* material rather than
   *  sliding it, so the stroke thins under the cursor and bulges around it.
   *  Pressure is 1 with the cursor on the ring, fading to 0 at `reach`. */
  liquid: number;
  /** Distance from the ring (either side) over which liquid pressure fades
   *  to zero, px. Keep this small — a large value lets a cursor sitting
   *  inside the button push the whole ring outward, which reads as a scale. */
  liquidReach: number;
  /** Spring constant for the liquid push. Lower = slower swell. */
  liquidStiffness: number;
  /** Damping for the liquid push. Below 2·√k it overshoots on release. */
  liquidDamping: number;
  /** Spring on the displacement vector — snap back speed. */
  stiffness: number;
  /** Below 2·√(k·m) the surface wobbles after release. */
  damping: number;
  mass: number;
  /** Blob-centre tracking, as a per-frame lerp at 60 Hz (0..1); applied
   *  time-based so 120 Hz pointers don't track twice as hard. Lower = the
   *  blob lags and stretches behind the cursor — stickier. */
  follow: number;
  /** Map resolution multiplier. 1 = one texel per CSS px, 2 = device parity
   *  on a 2× display. Steps in the field are visible below device parity. */
  mapRes: number;
  /** Post-displacement blur, CSS px. `feDisplacementMap` samples the source
   *  nearest-neighbour, which shows as stepping where material is stretched;
   *  a quarter-pixel blur hides it. 0 disables. */
  smooth: number;
}

export const BEND_DEFAULTS: Readonly<BendConfig> = Object.freeze({
  enabled: true,
  applyTo: 'ring',
  strength: 0.74,
  fadeInMs: 200,
  fadeOutMs: 350,
  smoothMs: 140,
  reach: 36,
  blob: 13,
  liquidBlob: 10,
  maxDisp: 9,
  gain: 0.6,
  pressGain: 0.55,
  pullGain: 0.49,
  press: 5,
  liquid: 7.5,
  liquidReach: 8,
  liquidStiffness: 53,
  liquidDamping: 9,
  stiffness: 260,
  damping: 13,
  mass: 1,
  follow: 0.32,
  mapRes: 2,
  smooth: 0.25,
});

export const BEND: BendConfig = { ...BEND_DEFAULTS };

export function setBendConfig(patch: Partial<BendConfig>): void {
  Object.assign(BEND, patch);
}

export function resetBendConfig(): void {
  Object.assign(BEND, BEND_DEFAULTS);
}

import { useEffect, type RefObject } from 'react';
import { textMaskDataUrl } from './engine/textMask';

/**
 * Confine a proximity reflection to an element's glyphs.
 *
 * The engine paints reflections into a wrapper it inserts inside the target
 * (`[data-metal-fx-reflection]`, canvases inset:0). For a text node that
 * would light the whole line box and stroke its rectangle. This masks the
 * wrapper with the text rendered white-on-transparent, so only the
 * letterforms catch the light. Re-rendered on resize and once fonts load.
 */
export function useMetalTextReflection(ref: RefObject<HTMLElement | null>): void {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Tells the engine to light this as letterforms, not as a chip: mirrored
    // metal only, no rim stroke / border highlight.
    el.setAttribute('data-metal-fx-text', '');
    let raf = 0;
    let disposed = false;
    let tries = 0;

    const apply = () => {
      if (disposed) return;
      const wrap = el.querySelector<HTMLElement>(':scope > [data-metal-fx-reflection]');
      // Engine attaches the wrapper after mount (and only in dark theme) —
      // wait a few seconds for it, then give up quietly.
      if (!wrap) { if (tries++ < 300) raf = requestAnimationFrame(apply); return; }
      tries = 0;
      const url = textMaskDataUrl(el, el);
      if (!url) return;
      const v = `url("${url}")`;
      wrap.style.maskImage = v;
      wrap.style.webkitMaskImage = v;
      wrap.style.maskRepeat = 'no-repeat';
      wrap.style.webkitMaskRepeat = 'no-repeat';
      wrap.style.maskSize = '100% 100%';
      wrap.style.webkitMaskSize = '100% 100%';
      // A mirror *replaces* what's under it. Additive blending on light-grey
      // text pushed everything to white and erased the metal's stripes and
      // dispersion fringes; normal compositing keeps them.
      wrap.style.mixBlendMode = 'normal';
    };

    apply();
    const ro = new ResizeObserver(() => apply());
    ro.observe(el);
    document.fonts?.ready.then(() => apply());
    // The engine tears down and re-inserts the wrapper whenever the owning
    // MetalFx's reflection effect re-runs — every new wrapper needs the mask.
    const mo = new MutationObserver((recs) => {
      for (const r of recs) {
        for (const n of Array.from(r.addedNodes)) {
          if (n instanceof HTMLElement && n.hasAttribute('data-metal-fx-reflection')) { apply(); return; }
        }
      }
    });
    mo.observe(el, { childList: true });

    return () => {
      disposed = true;
      if (raf) cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
    };
  }, [ref]);
}
